sqlite3 -json "/data/arabic_dict.db" "SELECT e.id AS entry_id, e.dictionary_id, e.headword, e.headword_bare, e.headword_norm, e.root, e.root_source, e.pos, e.definitions_text, e.translation_en, e.domain, d.key AS dict_key, d.name_ar AS dict_name_ar, d.source_type, d.period, d.author, d.death_year FROM entries e JOIN dictionaries d ON e.dictionary_id = d.id WHERE e.headword_norm IN ('اطناب','الاطناب','حشو','الحشو','اسهاب','الاسهاب','تطويل','التطويل','ثرثرة','الثرثرة','تفيهق','التفيهق') ORDER BY e.headword_norm, d.source_type, d.death_year ASC NULLS LAST;" 2>/dev/null | python3 -c "
import json,sys
data=json.load(sys.stdin)
for r in data:
    print(f\"[{r['entry_id']}] {r['headword']} | dict:{r['dict_name_ar']} | src:{r['source_type']} | pos:{r['pos']} | root:{r['root']}\")
    if r.get('definitions_text'): print(f\"  DEF: {r['definitions_text'][:200]}\")
    if r.get('translation_en'): print(f\"  EN: {r['translation_en']}\")
    if r.get('domain'): print(f\"  DOM: {r['domain']}\")
    print()
"
